"""Functions for working with large language models (LLMs)."""





def get_client(config: dict) -> OpenAI:
    """Get an OpenAI client instance."""
    if not config.get("LLM_MODEL"):
        raise ValueError("No LLM specified")
    return OpenAI(base_url=config.get("LLM_BASE_URL"))


def sanitize_answer(answer: str) -> str:
    """Sanitize the LLM answer."""
    # some models convert relative URLs to absolute URLs with this domain
    answer = answer.replace("https://www.example.com", "")
    return answer


def answer_prompt(prompt: str, system_prompt: str, config: dict | None = None) -> str:
    """Answer a question given a system prompt."""
    if not config:
        if current_app:
            config = current_app.config
        else:
            raise ValueError("Outside of the app context, config needs to be provided")

    messages = []

    if system_prompt:
        messages.append(
            {
                "role": "system",
                "content": str(system_prompt),
            }
        )

    messages.append(
        {
            "role": "user",
            "content": str(prompt),
        }
    )

    client = get_client(config=config)
    model = config.get("LLM_MODEL")
    assert model is not None, "No LLM model specified"  # mypy; shouldn't happen

    try:
        response = client.chat.completions.create(
            messages=messages,  # type: ignore
            model=model,
        )
    except RateLimitError:
        abort_with_message(500, "Chat API rate limit exceeded.")
    except APIError:
        abort_with_message(500, "Chat API error encountered.")
    except Exception:
        abort_with_message(500, "Unexpected error.")

    try:
        answer = response.to_dict()["choices"][0]["message"]["content"]  # type: ignore
    except (KeyError, IndexError):
        abort_with_message(500, "Error parsing chat API response.")
        raise  # mypy; unreachable

    return sanitize_answer(answer)


def answer_prompt_with_context(prompt: str, context: str) -> str:

    system_prompt = (
        "You are an assistant for answering questions about a user's family history. "
        "Use the following pieces of context retrieved from a genealogical database "
        "to answer the question. "
        "If you don't know the answer, just say that you don't know. "
        "Use three sentences maximum and keep the answer concise."
        "In your answer, preserve relative Markdown links."
    )

    system_prompt = f"""{system_prompt}\n\n{context}"""
    return answer_prompt(prompt=prompt, system_prompt=system_prompt)


def contextualize_prompt(prompt: str, context: str) -> str:

    system_prompt = (
        "Given a chat history and the latest user question "
        "which might reference context in the chat history, "
        "formulate a standalone question which can be understood "
        "without the chat history. Do NOT answer the question, "
        "just reformulate it if needed and otherwise return it as is."
    )

    system_prompt = f"""{system_prompt}\n\n{context}"""

    return answer_prompt(prompt=prompt, system_prompt=system_prompt)


def retrieve(tree: str, prompt: str, include_private: bool, num_results: int = 10):
    searcher = get_semantic_search_indexer(tree)
    total, hits = searcher.search(
        query=prompt,
        page=1,
        pagesize=num_results,
        include_private=include_private,
        include_content=True,
    )
    return [hit["content"] for hit in hits]


def answer_prompt_retrieve(
    prompt: str,
    tree: str,
    include_private: bool,
    history: list | None = None,
) -> str:
    logger = get_logger()

    if not history:
        # no chat history present - we directly retrieve the context

        search_results = retrieve(
            prompt=prompt, tree=tree, include_private=include_private, num_results=20
        )
        if not search_results:
            abort_with_message(500, "Unexpected problem while retrieving context")

        context = ""
        max_length = current_app.config["LLM_MAX_CONTEXT_LENGTH"]
        for search_result in search_results:
            if len(context) + len(search_result) > max_length:
                break
            context += search_result + "\n\n"
        context = context.strip()

        logger.debug("Answering prompt '%s' with context '%s'", prompt, context)
        logger.debug("Context length: %s characters", len(context))
        return answer_prompt_with_context(prompt=prompt, context=context)

    # chat history is present - we first need to call the LLM to merge the history
    # and the prompt into a new, standalone prompt.

    context = ""
    for message in history:
        if "role" not in message or "message" not in message:
            raise ValueError(f"Invalid message format: {message}")
        if message["role"].lower() in ["ai", "system", "assistant"]:
            context += f"*Assistant message:* {message['message']}\n\n"
        elif message["role"].lower() == "error":
            pass
        else:
            context += f"*Human message:* {message['message']}\n\n"
    context = context.strip()

    logger.debug("Contextualizing prompt '%s' with context '%s'", prompt, context)
    new_prompt = contextualize_prompt(prompt=prompt, context=context)
    logger.debug("New prompt: '%s'", new_prompt)

    # we can now feed the standalone prompt into the same function but without history.
    return answer_prompt_retrieve(
        prompt=new_prompt, tree=tree, include_private=include_private
    )

"""Parser for raw DNA match data."""




SIDE_UNKNOWN = "U"
SIDE_MATERNAL = "M"
SIDE_PATERNAL = "P"


@dataclass
class SegmentColumnOrder:
    """Order of the columns of a DNA match table."""

    chromosome: int
    start_position: int
    end_position: int
    centimorgans: int
    num_snps: int | None = None
    side: int | None = None
    comment: int | None = None


def get_delimiter(rows: list[str]) -> str:
    """Guess the delimiter of a string containing a CSV-like table.

    It is assumed that the table has at least 4 columns and at least one
    row.
    """
    if rows[0].count("\t") >= 3:
        return "\t"
    if rows[0].count(",") >= 3:
        return ","
    if rows[0].count(";") >= 3:
        return ";"
    raise ValueError("Could not determine delimiter.")


def is_numeric(value: str) -> bool:
    """Determine if a string is number-like."""
    if value == "":
        return False
    try:
        float(value)
        return True
    except ValueError:
        pass
    if re.match(r"^\d[\d\.,]*$", value):
        return True
    return False


def cast_int(value: str) -> int:
    """Cast a string to an integer."""
    try:
        return int(value.replace(",", "").replace(".", ""))
    except (ValueError, TypeError):
        return 0


def cast_float(value: str) -> float:
    """Cast a string to a float."""
    value = value.replace(" ", "")
    if value.count(".") > 1:
        value = value.replace(".", "")
    if value.count(",") > 1:
        value = value.replace(",", "")
    if value.count(",") == 1 and value.count(".") == 0:
        value = value.replace(",", ".")
    try:
        return float(value)
    except ValueError:
        return 0.0


def has_header(rows: list[str], delimiter: str) -> bool:
    """Determine if the table has a header."""
    if len(rows) < 2:
        return False
    header = rows[0]
    if len(header) < 4:
        return False
    header_columns = header.split(delimiter)
    if any(is_numeric(column) for column in header_columns):
        return False
    return True


@overload
def find_column_position(
    column_names: list[str],
    condition: Callable[[str], bool],
    exclude_indices: Sequence[int],
    allow_missing: Literal[False],
) -> int: ...


@overload
def find_column_position(
    column_names: list[str],
    condition: Callable[[str], bool],
    exclude_indices: Sequence[int],
    allow_missing: Literal[True],
) -> int | None: ...


def find_column_position(
    column_names: list[str],
    condition: Callable[[str], bool],
    exclude_indices: Sequence[int],
    allow_missing: bool = False,
) -> int | None:
    """Find the position of a column in a list of column names or raise a ValueError."""
    for i, column in enumerate(column_names):
        if i in exclude_indices:
            continue
        if condition(column.lower().strip()):
            return i
    if allow_missing:
        return None
    raise ValueError("Column not found.")


def get_order(
    header: list[str] | None, data_columns: Sequence[Sequence[str | None]]
) -> SegmentColumnOrder:
    """Get the order of the columns."""
    if header is None:
        # use the default ordering of the DNASegmentMap Gramplet
        # https://gramps-project.org/wiki/index.php/Addon:DNASegmentMapGramplet
        if len(data_columns) >= 6:
            # check whether the 6th column contains side information
            if all(
                (not value) or (value in {SIDE_MATERNAL, SIDE_PATERNAL, SIDE_UNKNOWN})
                for value in data_columns[5]
            ):
                return SegmentColumnOrder(
                    chromosome=0,
                    start_position=1,
                    end_position=2,
                    centimorgans=3,
                    num_snps=4,
                    side=5,
                    comment=6,
                )
        return SegmentColumnOrder(
            chromosome=0,
            start_position=1,
            end_position=2,
            centimorgans=3,
            num_snps=4,
            comment=5,
        )
    exclude_indices: list[int] = []
    chromosome = find_column_position(
        header,
        lambda col: col.startswith("chr"),
        exclude_indices=exclude_indices,
        allow_missing=False,
    )
    exclude_indices.append(chromosome)
    start_position = find_column_position(
        header,
        lambda col: "start" in col,
        exclude_indices=exclude_indices,
        allow_missing=False,
    )
    exclude_indices.append(start_position)
    end_position = find_column_position(
        header,
        lambda col: "end" in col
        or "stop" in col
        or ("length" in col and "morgan" not in col),
        exclude_indices=exclude_indices,
        allow_missing=False,
    )
    exclude_indices.append(end_position)
    centimorgans = find_column_position(
        header,
        lambda col: col.startswith("cm") or "centimorgan" in col or "length" in col,
        exclude_indices=exclude_indices,
        allow_missing=False,
    )
    exclude_indices.append(centimorgans)
    num_snps = find_column_position(
        header,
        lambda col: "snp" in col,
        exclude_indices=exclude_indices,
        allow_missing=True,
    )
    if num_snps is not None:
        exclude_indices.append(num_snps)
    side = find_column_position(
        header,
        lambda col: col.startswith("side"),
        exclude_indices=exclude_indices,
        allow_missing=True,
    )
    if side is not None:
        exclude_indices.append(side)
    comment = find_column_position(
        header,
        lambda _: True,  # take the first column that has not been matched yet
        exclude_indices=exclude_indices,
        allow_missing=True,
    )
    return SegmentColumnOrder(
        chromosome=chromosome,
        start_position=start_position,
        end_position=end_position,
        centimorgans=centimorgans,
        num_snps=num_snps,
        side=side,
        comment=comment,
    )


def transpose_jagged_nested_list(
    data: Sequence[Sequence[str | None]],
) -> list[list[str | None]]:
    """Transpose a jagged nested list, replacing missing values with None."""
    return list(map(list, itertools.zip_longest(*data, fillvalue=None)))


def parse_raw_dna_match_string(raw_string: str) -> list[MatchSegment]:
    """Parse a raw DNA match string."""
    rows = raw_string.strip().split("\n")
    try:
        delimiter = get_delimiter(rows)
    except ValueError:
        return []
    header: list[str] | None
    if has_header(rows, delimiter):
        header = rows[0].split(delimiter)
        rows = rows[1:]
    else:
        header = None
    data = [row.split(delimiter) for row in rows]
    data_columns = transpose_jagged_nested_list(data)
    try:
        order = get_order(header, data_columns=data_columns)
    except ValueError:
        return []
    segments = []
    for row in rows:
        if row.strip() == "":
            continue
        try:
            match_segment = process_row(fields=row.split(delimiter), order=order)
        except (ValueError, TypeError):
            continue
        if match_segment:
            segments.append(match_segment)
    return segments


def process_row(fields: list[str], order: SegmentColumnOrder) -> MatchSegment | None:
    """Process a row of a DNA match table."""
    if len(fields) < 4:
        return None
    try:
        chromo = fields[order.chromosome].strip()
        start = cast_int(fields[order.start_position].strip())
        stop = cast_int(fields[order.end_position].strip())
        cms = cast_float(fields[order.centimorgans].strip())
        if order.num_snps is not None and len(fields) >= order.num_snps + 1:
            snp = cast_int(fields[order.num_snps].strip())
        else:
            snp = 0
        if order.side is not None and len(fields) >= order.side + 1:
            side = fields[order.side].strip().upper()
            if side not in {SIDE_MATERNAL, SIDE_PATERNAL}:
                side = SIDE_UNKNOWN
        else:
            side = SIDE_UNKNOWN
        if order.comment is not None and len(fields) >= order.comment + 1:
            comment = fields[order.comment].strip()
        else:
            comment = ""
    except (ValueError, TypeError):
        return None
    return {
        "chromosome": chromo,
        "start": start,
        "stop": stop,
        "side": side,
        "cM": cms,
        "SNPs": snp,
        "comment": comment,
    }

