def progress_callback_count(self, title: str = "", message: str = "") -> Callable:
    def callback(current: int, total: int, prev: int | None = None) -> None:
        if total == 0:
            return
        self.update_state(
            state="PROGRESS",
            meta={
                "current": current,
                "total": total,
                "progress": clip_progress(current / total),
                "title": title,
                "message": message,
            },
        )

    return callback


